import csv,json,re
from decimal import Decimal as D
from pathlib import Path
root=Path('workspace'); out=root/'deliverable'; docs=root/'documents'; lib=root/'library'
allowed={'close_policy.md','bank_rec_standard.md'}
for f in [out/'bank_reconciliation.md',out/'open_items.md']:
 s=f.read_text()
 for target in re.findall(r'\\]\\((["'^)]+)'"\\)',s):
  assert target.startswith('../library/') and Path(target).name in allowed,(f,target)
 for name in re.findall(r'"'`([''^`]+'"\\.(?:csv|pdf))"'`'"',s):
  assert (docs/name).is_file(),(f,name)
e=json.loads((out/'adjusting_entries.json').read_text(),parse_float=D)
t=json.loads((out/'trial_balance_2026-03-31.json').read_text(),parse_float=D)
coa={r['account'] for r in csv.DictReader((docs/'chart_of_accounts.csv').open())}
assert set(t['accounts'])==coa
v={a:D(0) for a in coa}
for r in csv.DictReader((docs/'trial_balance_2026-02-28.csv').open()):v[r['account']]+=D(r['debit'] or 0)-D(r['credit'] or 0)
for r in csv.DictReader((docs/'general_ledger_2026-03.csv').open()):
 if '2026-03-01'<=r['date']<='2026-03-31':v[r['account']]+=D(r['debit'] or 0)-D(r['credit'] or 0)
for x in e:
 assert sum((r['debit'] for r in x['lines']),D(0))==sum((r['credit'] for r in x['lines']),D(0)),x['ref']
 for r in x['lines']:v[r['account']]+=r['debit']-r['credit']
for a,n in v.items():
 assert t['accounts'][a]['debit']-t['accounts'][a]['credit']==n,(a,n,t['accounts'][a])
assert sum((r['debit'] for r in t['accounts'].values()),D(0))==sum((r['credit'] for r in t['accounts'].values()),D(0))==D('424932.07')
assert D('7625.50')+D('6250')-D('612.40')-D('2944.80')==D('10318.30')
assert D('6041.30')+D('4312')-D('35')==D('10318.30')
print('Audit passed: authority links indexed, evidence filenames exist, seven AJEs balance, TB reproduces source rollforward, bank sides agree.')
PY"

